content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
}

body {
  background-color: #f5f7fa;
  color: #333;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem;
  width: 100%;
  max-width: 480px;
}

.timer-card {
  background: #ffffff;
  padding: 2.5rem 2rem;
  border-radius: 20px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.05);
  text-align: center;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.status-text {
  font-size: 1.2rem;
  font-weight: 600;
  color: #e53935;
  margin-bottom: 1rem;
}

.timer-display {
  font-size: 5rem;
  font-weight: 700;
  color: #2d3748;
  margin: 1.5rem 0;
  letter-spacing: -2px;
}

.controls {
  display: flex;
  gap: 1rem;
  margin-top: 1.5rem;
  width: 100%;
  justify-content: center;
}

.btn {
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.1s ease, background-color 0.2s ease;
  flex: 1;
}

.btn:active {
  transform: scale(0.97);
}

.btn-start {
  background-color: #48bb78;
  color: white;
}

.btn-start:hover {
  background-color: #38a169;
}

.btn-pause {
  background-color: #ed8936;
  color: white;
}

.btn-pause:hover {
  background-color: #dd6b20;
}

.btn-reset {
  background-color: #e2e8f0;
  color: #4a5568;
}

.btn-reset:hover {
  background-color: #cbd5e0;
}

import { useState, useEffect, useRef } from 'react';
import './index.css';

export default function App() {
  const TOTAL_TIME = 1500; // 25 minutes in seconds
  const [timeLeft, setTimeLeft] = useState<number>(TOTAL_TIME);
  const [isRunning, setIsRunning] = useState<boolean>(false);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    if (isRunning) {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            setIsRunning(false);
            clearInterval(timerRef.current!);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } else {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    }

    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    };
  }, [isRunning]);

  const handleStart = () => {
    if (timeLeft > 0) {
      setIsRunning(true);
    }
  };

  const handlePause = () => {
    setIsRunning(false);
  };

  const handleReset = () => {
    setIsRunning(false);
    setTimeLeft(TOTAL_TIME);
  };

  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;
  const formattedTime = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

  let statusText = '集中タイム';
  if (!isRunning && timeLeft === TOTAL_TIME) {
    statusText = '準備完了';
  } else if (!isRunning && timeLeft > 0 && timeLeft < TOTAL_TIME) {
    statusText = '一時停止中';
  } else if (timeLeft === 0) {
    statusText = '時間切れ！お疲れ様でした';
  }

  return (
    <div className="app-container">
      <div className="timer-card">
        <div className="status-text">{statusText}</div>
        <div className="timer-display">{formattedTime}</div>
        <div className="controls">
          {!isRunning ? (
            <button className="btn btn-start" onClick={handleStart}>
              開始
            </button>
          ) : (
            <button className="btn btn-pause" onClick={handlePause}>
              一時停止
            </button>
          )}
          <button className="btn btn-reset" onClick={handleReset}>
            リセット
          </button>
        </div>
      </div>
    </div>
  );
}
